    c = copy.deepcopy(base_cfg)
    c.experiment_name = f"{base_cfg.experiment_name}_seed{seed}"
    c.wandb_run_name  = f"{base_cfg.wandb_run_name or base_cfg.experiment_name}_seed{seed}"
    return c
